import manifest from './image-manifest.json';

/**
 * Generated by `npm run images:optimize`. Maps a product slug to the number of real
 * photos available (1..n, contiguous). Missing slugs fall back to generated placeholders.
 */
const photos: Readonly<Record<string, number>> = manifest;

export function photoCount(slug: string): number {
  return photos[slug] ?? 0;
}

export function photoSrc(slug: string, index: number): string {
  return `/images/products/${slug}/${index + 1}`;
}
